<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {Bot,Folder,FileText,GitBranch,RefreshCw,Send,Square,Plus,Terminal,Check} from 'lucide-vue-next'
import DetailTabs from '@/components/ui/DetailTabs.vue'
import type {ProjectItem,ProjectOverview,ProjectSession,ProjectSessionSummary,ProjectMessage} from '@/types/project'
const props=defineProps<{item:ProjectItem}>(),emit=defineEmits<{updated:[]}>(),router=useRouter(),route=useRoute(),tab=ref('overview')
const tabs=[{id:'overview',label:'工作区概览'},{id:'chat',label:'项目助手'},{id:'entries',label:'项目入口'},{id:'info',label:'项目资料'}]
watch(()=>route.query.tab,value=>{tab.value=tabs.some(t=>t.id===value)?String(value):'overview'},{immediate:true})
watch(tab,value=>{if(route.query.tab!==value)void router.replace({query:{...route.query,tab:value}})})
const overview=ref<ProjectOverview|null>(null),loading=ref(false),error=ref(''),sessions=ref<ProjectSessionSummary[]>([]),session=ref<ProjectSession|null>(null),selected=ref(''),input=ref(''),messages=ref<HTMLElement>(),submitting=ref(false)
const busy=computed(()=>submitting.value||session.value?.status==='running')
let revision=0,disposed=false
async function refresh(){loading.value=true;error.value='';const run=++revision;try{const result=await window.baoyi.project.overview(props.item.id);if(run===revision)overview.value=result}catch(e){if(run===revision)error.value=(e as Error).message}finally{if(run===revision)loading.value=false}}
async function loadSessions(){sessions.value=await window.baoyi.project.sessions(props.item.id);if(!session.value&&sessions.value.length){selected.value=sessions.value[0].id;session.value=await window.baoyi.project.session(selected.value)}}
watch(()=>props.item.id,async()=>{session.value=null;selected.value='';await refresh();try{await loadSessions()}catch(e){error.value=(e as Error).message}},{immediate:true})
async function switchSession(){error.value='';try{session.value=await window.baoyi.project.session(selected.value)}catch(e){error.value=(e as Error).message}}
async function newSession(){error.value='';try{session.value=await window.baoyi.project.createSession(props.item.id);selected.value=session.value.id;await loadSessions();tab.value='chat'}catch(e){error.value=(e as Error).message}}
async function send(text=input.value){if(busy.value||!text.trim())return;submitting.value=true;error.value='';tab.value='chat';try{
  if(!session.value)await newSession();if(!session.value)return
  input.value='';const result=await window.baoyi.project.sendMessage(session.value.id,text)
  if(!disposed&&selected.value===result.id){session.value=result;await loadSessions()}
}catch(e){error.value=(e as Error).message;input.value=text}finally{submitting.value=false}}
async function stop(){if(session.value)try{await window.baoyi.project.cancelMessage(session.value.id)}catch(e){error.value=(e as Error).message}}
async function apply(message:ProjectMessage){if(!session.value)return;error.value='';try{session.value=await window.baoyi.project.applyProposal(session.value.id,message.id);emit('updated')}catch(e){error.value=(e as Error).message}}
const labels:Record<string,string>={name:'名称',summary:'简介',category:'分类',source:'来源',state:'状态',group:'分组',tags:'标签',notes:'备注'}
const display=(value:unknown)=>Array.isArray(value)?value.join('、'):String(value||'（空）')
const unsubscribe=window.baoyi.project.onSession(value=>{if(value.projectId!==props.item.id||value.id!==selected.value)return;session.value=value;void nextTick(()=>{if(messages.value)messages.value.scrollTop=messages.value.scrollHeight})})
onBeforeUnmount(()=>{disposed=true;revision++;unsubscribe()})
function key(event:KeyboardEvent){if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();void send()}}
</script>
<template><section class="project-workbench"><DetailTabs v-model="tab" :tabs="tabs" prefix="project" label="项目详情"/><p v-if="error" class="pj-error" role="alert">{{error}}</p>
<div v-show="tab==='overview'" id="project-panel-overview" role="tabpanel" aria-labelledby="project-tab-overview" class="workspace-overview"><div class="workspace-title"><div><h2>从这里了解项目</h2><p>目录、启动脚本与工作区状态</p></div><button class="pj-button" :disabled="loading" @click="refresh"><RefreshCw :size="15"/>刷新概览</button><button class="pj-button pj-primary" :disabled="busy" @click="send('阅读项目说明，解释这个项目的用途和主要入口，再给出有依据的项目资料建议。')"><Bot :size="16"/>让助手了解项目</button></div><div v-if="sessions.length" class="registration-status"><Bot :size="17"/><span>{{sessions[0].title==='导入登记'?'已登记，可分析':'已有项目分析记录'}}<small v-if="session?.status==='failed'"> · 上次分析未完成，可重试</small></span><button class="pj-button" @click="tab='chat'">查看助手记录</button></div><p v-if="loading">正在读取项目…</p><div v-if="overview" class="workspace-grid"><div class="workspace-files"><h3>目录内容 <span>{{overview.files.length}}</span></h3><ul><li v-for="file in overview.files.slice(0,40)" :key="file.path"><Folder v-if="file.directory" :size="14"/><FileText v-else :size="14"/><span>{{file.path}}</span></li></ul><p v-if="overview.files.length>40">显示前 40 项，助手可按目录继续读取。</p></div><div><section class="workspace-git"><h3><GitBranch :size="16"/>Git 状态</h3><template v-if="overview.git.available"><strong>{{overview.git.branch}}</strong><p>{{overview.git.changed?overview.git.changed+' 个文件有变化':'工作区干净'}}</p><pre v-if="overview.git.status">{{overview.git.status}}</pre><button class="pj-button" :disabled="busy" @click="send('请检查当前项目的 Git 状态，并读取相关文件，说明当前改动涉及哪些工作。')">请助手解释当前状态</button></template><p v-else>{{overview.git.message}}</p></section><section class="workspace-scripts"><h3><Terminal :size="16"/>项目脚本</h3><div v-for="script in overview.scripts" :key="script.name"><strong>{{script.name}}</strong><code>{{script.command}}</code></div><p v-if="!overview.scripts.length">没有读取到 package.json 脚本，可从项目入口打开常用工具。</p><p v-else>在外部终端中运行，点击概览不会执行脚本。</p></section></div></div></div>
<div v-show="tab==='chat'" id="project-panel-chat" role="tabpanel" aria-labelledby="project-tab-chat" class="project-chat"><div class="chat-toolbar"><select v-model="selected" aria-label="项目对话" :disabled="busy" @change="switchSession"><option v-if="!sessions.length" value="">新对话</option><option v-for="s in sessions" :key="s.id" :value="s.id">{{s.title}}</option></select><button class="pj-button" :disabled="busy" @click="newSession"><Plus :size="15"/>新对话</button><button class="pj-button" @click="router.push({name:'settings',query:{tab:'project'}})">助手设置</button><span v-if="session?.tokens">{{session.tokens}} tokens</span></div><div ref="messages" class="chat-messages" aria-live="polite"><div v-if="!session?.messages.length" class="chat-welcome"><Bot :size="32"/><h3>围绕这个项目，接着聊</h3><p>从目录、说明文档和 Git 状态中寻找依据。</p><div><button @click="send('请阅读项目说明，解释用途和主要入口。')">这个项目怎么用？</button><button @click="send('根据当前项目资料和文件，建议下一步可以做什么。')">接下来做什么？</button><button @click="send('读取文件证据，帮我完善简介、分类和标签，并提出修改建议。')">完善项目资料</button></div></div><article v-for="message in session?.messages||[]" :key="message.id" class="chat-message" :class="message.role"><span class="chat-author">{{message.role==='user'?'你':'抱一助手'}}</span><details v-if="message.events.length" class="chat-trace"><summary>处理过程 · {{message.events.length}} 条记录</summary><div v-for="(event,i) in message.events" :key="i" :class="{'trace-error':event.error}"><strong>{{event.label}}</strong><pre>{{event.detail}}</pre></div></details><p class="chat-text">{{message.text||'正在查看项目…'}}</p><section v-if="message.proposal" class="chat-proposal"><h4>项目资料建议</h4><div v-for="(value,key) in message.proposal.patch" :key="key"><strong>{{labels[key]||key}}</strong><span class="proposal-before">{{display(message.proposal.before[key])}}</span><span>{{display(value)}}</span></div><button class="pj-button pj-primary" :disabled="busy||message.proposal.applied" @click="apply(message)"><Check :size="15"/>{{message.proposal.applied?'已应用':'应用资料建议'}}</button></section></article><p v-if="session?.error" class="chat-error" role="status">{{session.error}}</p></div><form class="chat-composer" @submit.prevent="send()"><textarea v-model="input" aria-label="给项目助手发消息" placeholder="问问项目用途、当前状态，或请助手完善资料…" maxlength="12000" :disabled="busy" @keydown="key"/><div><span>Enter 发送 · Shift Enter 换行</span><button v-if="busy" type="button" class="pj-button" @click="stop"><Square :size="14"/>停止</button><button v-else class="pj-button pj-primary" type="submit" :disabled="!input.trim()"><Send :size="15"/>发送</button></div></form></div><div v-show="tab==='entries'" id="project-panel-entries" role="tabpanel" aria-labelledby="project-tab-entries" class="workbench-content"><slot name="entries"/></div><div v-show="tab==='info'" id="project-panel-info" role="tabpanel" aria-labelledby="project-tab-info" class="workbench-content"><slot name="info"/></div></section></template>
<style scoped>
.registration-status{display:flex;align-items:center;gap:10px;margin-top:18px;padding:12px 14px;background:var(--active-surface);border-radius:8px;color:var(--text-sub);font-size:12px}.registration-status>span{flex:1}.project-workbench>.detail-tabs{padding:0 20px}.workbench-content{padding:24px}.project-workbench{margin:20px 0;background:var(--bg-card);border:1px solid var(--divider);border-radius:12px;overflow:hidden}.workbench-tabs{display:flex;align-items:center;border-bottom:1px solid var(--divider);padding:0 22px;gap:24px}.workbench-tabs>button{display:flex;align-items:center;gap:8px;padding:17px 0;color:var(--text-sub);border-bottom:2px solid transparent;font-size:14px}.workbench-tabs>button.active{color:var(--accent);border-bottom-color:var(--accent)}.workbench-tabs>.workbench-settings{margin-left:auto;font-size:12px}.working-dot{width:6px;height:6px;background:var(--accent);border-radius:50%}.workspace-overview{padding:24px}.workspace-title{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.workspace-title>div{margin-right:auto}.workspace-title h2{font-size:19px;margin:0 0 6px}.workspace-title p,.workspace-grid p{font-size:12px;color:var(--text-sub);line-height:1.8}.workspace-grid{display:grid;grid-template-columns:1fr 1.1fr;gap:30px;margin-top:18px}.workspace-grid h3{display:flex;align-items:center;gap:8px;font-size:13px;margin:0 0 16px}.workspace-grid h3 span{color:var(--text-faint);font-weight:400}.workspace-files ul{list-style:none;padding:0;margin:0;max-height:340px;overflow:auto}.workspace-files li{display:flex;align-items:center;gap:9px;padding:7px 0;color:var(--text-sub);font-size:12px;overflow-wrap:anywhere}.workspace-git{padding-bottom:20px}.workspace-git>strong{font-size:13px;color:var(--accent)}.workspace-git pre{font-size:11px;white-space:pre-wrap;max-height:140px;overflow:auto;color:var(--text-sub)}.workspace-scripts{max-height:280px;overflow:auto;border-top:1px solid var(--divider);padding-top:18px}.workspace-scripts>div{display:flex;gap:12px;font-size:12px;margin:10px 0}.workspace-scripts strong{min-width:60px;font-weight:500}.workspace-scripts code{overflow-wrap:anywhere;color:var(--text-sub)}.project-chat{max-width:1000px;margin:auto}.chat-toolbar{display:flex;align-items:center;gap:12px;padding:16px 22px;border-bottom:1px solid var(--divider)}.chat-toolbar select{flex:1;min-width:0;max-width:500px}.chat-toolbar>span{margin-left:auto;font-size:11px;color:var(--text-faint)}.chat-messages{height:450px;overflow:auto;padding:24px}.chat-welcome{text-align:center;padding:48px 10px;color:var(--text-sub)}.chat-welcome h3{color:var(--text-main);font-size:20px;font-weight:500}.chat-welcome p{font-size:13px}.chat-welcome>div{display:flex;justify-content:center;gap:10px;flex-wrap:wrap;margin-top:24px}.chat-welcome button{border:1px solid var(--divider);padding:9px 14px;border-radius:7px;font-size:12px}.chat-message{margin:0 0 24px}.chat-message.user{background:var(--hover-surface);border-radius:8px;padding:14px 18px;margin-left:48px}.chat-author{font-size:11px;color:var(--text-faint)}.chat-text{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:1.85;margin:7px 0}.chat-trace{margin-top:10px;border:1px solid var(--divider);border-radius:7px;font-size:12px;color:var(--text-sub)}.chat-trace summary{cursor:pointer;padding:10px}.chat-trace>div{padding:10px;border-top:1px solid var(--divider)}.chat-trace pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:160px;overflow:auto;font-size:11px}.trace-error,.chat-error{color:var(--danger)}.chat-proposal{padding:18px;background:var(--active-surface);border-radius:8px}.chat-proposal h4{margin:0 0 14px;font-size:13px}.chat-proposal>div{display:grid;grid-template-columns:60px 1fr 1fr;gap:14px;padding:10px 0;font-size:12px;border-top:1px solid var(--divider);white-space:pre-wrap;overflow-wrap:anywhere}.proposal-before{color:var(--text-faint)}.chat-proposal button{margin-top:14px}.chat-composer{border-top:1px solid var(--divider);padding:16px 22px}.chat-composer textarea{width:100%;min-height:76px;max-height:220px;resize:vertical;background:transparent;border:0;outline:0;font:inherit;font-size:14px;line-height:1.7}.chat-composer>div{display:flex;justify-content:space-between;align-items:center}.chat-composer>div>span{font-size:11px;color:var(--text-faint)}@media(max-width:1100px){.workspace-grid{gap:18px}.workspace-title .pj-button{font-size:12px}.chat-proposal>div{grid-template-columns:50px 1fr 1fr}}
@media(max-width:800px){.workspace-grid{grid-template-columns:minmax(0,1fr)}.workspace-overview,.registration-status{display:flex;align-items:center;gap:10px;margin-top:18px;padding:12px 14px;background:var(--active-surface);border-radius:8px;color:var(--text-sub);font-size:12px}.registration-status>span{flex:1}.project-workbench>.detail-tabs{padding:0 20px}.workbench-content{padding:16px}.chat-toolbar{flex-wrap:wrap}.chat-messages{height:360px}}
</style>
